package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamPolonnaruwaBank1 {
    private const val T = "පොළොන්නරු යුගයේ සිතුවම් හා මූර්ති කලාව"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("පොළොන්නරු යුගයේ බිතුසිතුවම් කලාවේ විශිෂ්ටතම හා විශාලතම සිතුවම් ගබඩාව ලෙස සැලකෙන විහාර ගොඩනැගිල්ල කුමක්ද?", "තිවංක පිළිමගෙය", "ගල් විහාර පිළිමගෙය", "ලංකාතිලක කෝවිල", "සත්මහල් ප්‍රාසාදය", "මහා පරාක්‍රමබාහු රජු විසින් කරවන ලද තිවංක පිළිමගෙයි ඇතුළත බිත්ති සම්පූර්ණයෙන්ම බිතුසිතුවමින් සරසා තිබිණි."),
        q("තිවංක පිළිමගෙය ඉදිකරවා සිතුවම් කළ පොළොන්නරු යුගයේ ප්‍රධාන රජතුමා කවුද?", "පළමුවන මහා පරාක්‍රමබාහු රජතුමා", "නිශ්ශංකමල්ල රජතුමා", "පළමුවන කාශ්‍යප රජතුමා", "ශ්‍රී වීර පරාක්‍රම නරේන්ද්‍රසිංහ රජු", "ක්‍රි.ව. 12 වන සියවසේ මහා පරාක්‍රමබාහු රජුගේ කාලයේදී තිවංක පිළිමගෙය ඉදි කෙරිණි."),
        q("තිවංක පිළිමගෙයි අන්තරාලයේ හා ගර්භගෘහයේ බිත්තිවල සිතුවම් කර ඇති ප්‍රධාන තේමා කවරේද?", "ජාතක කතා, දේවාරාධනාව හා සංකස්සපුර දේවාවරෝහණය", "සීගිරි ලලනාවන් හා රජ මාලිගා", "පෘතුගීසි ආක්‍රමණ හා නැව් සටන්", "වැදි ජනතාවගේ දඩයම් දර්ශන", "බුදු සිරිතේ වැදගත් අවස්ථා හා ජාතක කතා විශාල ප්‍රමාණයක් තිවංක පිළිමගෙයි සිතුවම් කර ඇත."),
        q("තිවංක පිළිමගෙයි ඇතුළු වන මණ්ඩපයේ (අන්තරාලයේ) බිත්තිවල ඇඳ ඇති සුප්‍රකට ජාතක කතා අතරට අයත් වන්නේ මොනවාද?", "සස ජාතකය, වෙස්සන්තර ජාතකය, මෛත්‍රීබල හා කාලගෝල කතා", "මහෞෂධ පඬිතුමාගේ කතා පමණක්", "කුවේණි අස්න හා විජය පුවත", "රාමායණය හා මහාභාරතය", "සස ජාතකයේ හාවා හා තව්තිසා සිට බැසීම ඇතුළු ජාතක කතා රැසක් තිවංක බිත්තිවල වේ."),
        q("තිවංක පිළිමගෙයි ඇඳ ඇති 'සස ජාතකය' සිතුවමෙහි ප්‍රධාන වශයෙන් නිරූපණය කර ඇති සිදුවීම කුමක්ද?", "සාවා ගින්නට පැනීමට සූදානම් වීම හා සක්‍රයා සාවා සඳ මත ඇඳීම", "රජෙකු ඇතෙකු පිට යුද්ධයට යාම", "ධීවරයෙකු මසුන් ඇල්ලීම", "කාන්තාවන් කළගෙඩි රැගෙන යාම", "බෝසත් සාවා දාන පාරමිතාව පුරමින් ගින්නට පනින පුවත ඉතා සංවේදී ලෙස සිතුවම් කර ඇත."),
        q("තිවංක පිළිමගෙයි ගර්භගෘහයේ උතුරු බිත්තියේ ඇති 'සංකස්සපුර දේවාවරෝහණය' සිතුවමින් දැක්වෙන්නේ කුමක්ද?", "තව්තිසාවෙන් සංකස්සපුරයට වැඩමවීම", "විජය කුමරු තම්බපණ්ණියට පැමිණීම", "මිහිඳු හිමි මිහින්තලයට වැඩමවීම", "කාශ්‍යප රජු සීගිරියට නැගීම", "බ්‍රහ්ම හා ශක්‍ර දේව පිරිවර සමඟ බුදුන් වහන්සේ වැඩම කරන දර්ශනය මෙහි විශිෂ්ටව දැක්වේ."),
        q("තිවංක පිළිමගෙයි දකුණු බිත්තියේ ඇති 'දේවාරාධනාව' සිතුවමෙහි නිරූපණය වන අවස්ථාව කුමක්ද?", "තුසිත දෙව්ලොව දේව ආරාධනාව", "රාජ සභාවේ නැටුම් පැවැත්වීම", "වෙස්සන්තර රජු ඇතු දන් දීම", "දිය කැපීමේ මංගල්‍යය", "දිව්‍ය ආසන මත හිඳ බෝසතුන් හා දෙවිවරුන් සිටින සුන්දර සමූහ සංයුතියක් මෙහි දැක්වේ."),
        q("තිවංක පිළිමගෙයි 'බුදු සිරිත' නිරූපණය කරන සිතුවම් අතර 'අසංඛවතී' හෝ 'රුවන් සක්මන' වැනි අවස්ථාවල විශේෂත්වය කුමක්ද?", "බහු රූප සහිත සංකීර්ණ සංයුතිය හා චලන රිද්මය", "එකම තනි කළු රේඛාවක් පමණක් තිබීම", "කිසිදු මානව රූපයක් නොතිබීම", "පසුබිම කළු තීන්තවලින් වැසී තිබීම", "රූප රාශියක් එකිනෙකා සමඟ සම්බන්ධ කරමින් නාට්‍යමය ආඛ්‍යානයක් තිවංක සිතුවම් මවයි."),
        q("පොළොන්නරු යුගයේ තිවංක බිතුසිතුවම්වල බහුලව භාවිත කර ඇති ප්‍රධාන වර්ණ මොනවාද?", "රතු, කහ, කොළ, කළු සහ සුදු පෘථිවි වර්ණ (සමහර තැන්වල නිල්)", "තෙල් සායම් රෝස සහ දම්", "රන් හා රිදී ඇක්‍රිලික් පමණි", "තනි අළු හා කළු පමණි", "රතු ගුරුගල්, කහ ගුරුගල් සහ කොළ වර්ණ උණුසුම් හා ගාම්භීර පරිසරයක් මවයි."),
        q("තිවංක පිළිමගෙයි සිතුවම් ඇඳීමට භාවිත කළ බදාම ක්‍රමවේදය කුමක්ද?", "සීගිරියට සමාන වියළි බදාම ක්‍රමය", "තෙල් සායම් කැන්වස් ක්‍රමය", "ජල සායම් කඩදාසි ක්‍රමය", "මොසැයික් වීදුරු ඇතිරීම", "ගඩොල් බිත්තිය මත රළු මැටි හා හුණු බදාම තට්ටු දමා වියළි බදාමය මත වර්ණ යොදා ඇත."),
        q("සීගිරි සිතුවම් හා තිවංක පිළිමගෙයි සිතුවම් සැසඳීමේදී දක්නට ලැබෙන ප්‍රධාන තේමාත්මක වෙනස කුමක්ද?", "සීගිරිය තනි හා යුගල දිව්‍ය ලලනාවන් වන අතර තිවංක සම්පූර්ණ බෞද්ධ ආඛ්‍යාන කතා වීම", "සීගිරියේ බුදු රූප පමණක් ඇති අතර තිවංකයේ සතුන් පමණි", "දෙකම එකම කලාකරුවෙකු විසින් ඇඳීම", "තිවංක සිතුවම් ප්‍රාග් ඓතිහාසික ගුහා චිත්‍ර වීම", "තිවංක පිළිමගෙයි විශාල ආගමික කතා පුවත් සමූහ රූප මගින් ඉදිරිපත් කර ඇත."),
        q("තිවංක පිළිමගෙයි සිතුවම්වල 'සමූහ රූප සංයුතිය' (Group Composition) සකසා ඇති ආකාරය කෙබඳුද?", "පසුබිම් ඉඩ හිස් නොතබා මල්, ගස් හා දේව රූපවලින් රිද්මයානුකූලව පිරවීම", "සෑම රුවක්ම වෙනම රාමු තුළ වෙන් කිරීම", "මිනිසුන් සියල්ල එකම කෙළින් ඉරක හිටවීම", "රූප අතර මීටර් ගණන් හිස් බිත්ති තැබීම", "බිත්ති තලය පුරා රූප එකිනෙකා වෙත හැරී කතා කරන සේ ස්වභාවිකව ගොනු කර ඇත."),
        q("තිවංක පිළිමගෙයි 'බිතුසිතුවම් බෙදීමේදී' කතා පුවත් වෙන් කිරීමට භාවිත කළ අලංකරණ ක්‍රමය කුමක්ද?", "රතු හා කහ පටි, ලියවැල් හා ගොඩනැගිලි තීරු යෙදීම", "කළු තාර ඉරි ගැසීම", "සිංහල ඉලක්කම් 1, 2, 3 ලිවීම", "රන් කම්බි ඇණ ගැසීම", "තිරස් හා සිරස් රතු පටි හා මෝස්තර මගින් ජාතක කතා දර්ශන ක්‍රමානුකූලව වෙන් කර ඇත."),
        q("පොළොන්නරුවේ ගල් විහාරයේ 'විජ්ජාධර ගුහාව' තුළ දක්නට ලැබෙන පැරණි බිතුසිතුවම් ශේෂයන්ගෙන් නිරූපණය වන්නේ කුමක්ද?", "රැවුල සහිත මහලු දෙවිවරුන් හෝ බ්‍රහ්ම රූප හා මල් ලියවැල්", "නූතන ගොවි කතුන්ගේ දර්ශන", "මහනුවර පෙරහැරේ නැට්ටුවන්", "යුද නැව් හා කාලතුවක්කු", "විද්‍යාධර ගුහාවේ වම් බිත්තියේ බුදුන් වහන්සේට ගෞරව කරන බ්‍රහ්ම හා දේව රූප කොටස් තවමත් ඉතිරිය."),
        q("පොළොන්නරුවේ 'ගල් විහාර විජ්ජාධර ගුහාවේ' බිතුසිතුවම්වල භාවිත කර ඇති ප්‍රධාන සෙවණැලි ලක්ෂණය කුමක්ද?", "සම්භාව්‍ය ත්‍රිමාණ වර්ණ ආලේපනය", "සම්පූර්ණ පැතලි කොළ පසුබිම", "කළු-සුදු තිත් රටා පමණක් යෙදීම", "රන් කඩදාසි ඇලවීම", "අනුරාධපුර සම්භාව්‍ය ශෛලියේ අඛණ්ඩ සේයාව පොළොන්නරුවේ ගල් විහාර සිතුවම්වලද පවතී."),
        q("පොළොන්නරු යුගයේ දිඹුලාගල ප්‍රදේශයේ පිහිටි 'මාරවීදිය' ගල් ලෙනෙහි පැවති සිතුවම් අයත් වන්නේ කුමන කාලයකටද?", "පොළොන්නරු යුගයේ 12 වන සියවසට", "ප්‍රාග් ඓතිහාසික යුගයට", "බ්‍රිතාන්‍ය පාලන යුගයට", "21 වන සියවසට", "වික‍්‍රමබාහු රජුගේ බිසව සුන්දරමහා දේවිය කළ පූජාවන් හා බැඳුණු දිඹුලාගල මාරවීදියේ පොළොන්නරු සිතුවම් විය."),
        q("දිඹුලාගල ආසන්නයේ 'පුල්ලිගොඩ ගල්ගෙයි' සිතුවමේ පෙන්නුම් කරන විශේෂ දිව්‍ය රූප සංඛ්‍යාව කොපමණද?", "ප්‍රභා මණ්ඩල සහිත දේව රූප පහක් (5)", "කාන්තා රූප පනහක්", "මිනිස් රූප සියයක්", "එක් සිංහ රුවක් පමණක්", "නෙළුම් මල් පිදීමට හිඳගෙන සිටින ප්‍රභා මණ්ඩල සහිත දේව රූප පස්දෙනෙකු එහි දැකිය හැක."),
        q("පොළොන්නරු යුගයේ සිතුවම්වල 'සාදිලිංගම් සහ ගුරුගල්' මගින් නිර්මාණය කළ උණුසුම් රතු පසුබිම්වල ප්‍රයෝජනය කුමක්ද?", "ප්‍රධාන චරිතවල කහ හා සුදු පැහැයන් වඩාත් ඉස්මතු කර පෙන්වීම", "බිත්තිය සිසිල් කර තැබීම", "කෘමීන්ගෙන් බිත්තිය රැකීම", "වෙනත් වර්ණ මිලදී ගැනීමට නොහැකි වීම", "තද රතු-දුඹුරු පසුබිම්වලදී රන්වන් හා සුදු රූප නරඹන්නාට කැපී පෙනේ."),
        q("තිවංක පිළිමගෙයි සිතුවම්වල ඇඳ ඇති 'බුදුන් වහන්සේගේ පරිමාණය' අනෙක් පිරිවාර දෙවිවරුන්ට වඩා විශාල කර ඇත්තේ ඇයි?", "ප්‍රධානත්වය හා ගෞරවය දැක්වීමේ ශ්‍රේණිගත පරිමාණ රීතිය නිසා", "ශිල්පියාට සමානුපාතික දැනුමක් නොතිබූ නිසා", "දෙවිවරුන් ඉතා කුඩා ළදරුවන් වූ නිසා", "බිත්තියේ පහළ ඉඩ මදි වූ නිසා", "පෙරදිග ආගමික කලාවේ බුදුන් වහන්සේගේ උත්තරීතර බව පෙන්වීමට ශ්‍රේණිගත පරිමාණය යොදයි."),
        q("පොළොන්නරුවේ 'පොත්ගුල් වෙහෙර' ආශ්‍රිත ගොඩනැගිලි බිත්තිවල පැවති බිතුසිතුවම්වලින් හෙළි වන්නේ කුමක්ද?", "පොළොන්නරුවේ විහාර සංකීර්ණ බොහොමයක් ඇතුළතින් වර්ණවත් සිතුවමින් සරසා තිබූ බව", "පොත්ගුල් වෙහෙර පමණක් සුදු හුණු ගා තිබූ බව", "සිතුවම් කලාව පොළොන්නරුවේ තහනම් වූ බව", "පොත්ගුල් වෙහෙර මුහුද යට තිබූ බව", "පොත්ගුල් වෙහෙර, ලංකාතිලකය හා තිවංකය යන ස්ථානවල පැරණි බදාම සිතුවම් ශේෂ හමුවේ."),
        q("තිවංක පිළිමගෙයි බිතුසිතුවම්වල 'රේඛා ශෛලිය' අනුරාධපුර සීගිරි ශෛලියෙන් මඳක් වෙනස් වන්නේ කෙසේද?", "වඩාත් සියුම් විස්තරාත්මක රේඛා හා අලංකාර ආභරණ බහුල වීම", "රේඛා සම්පූර්ණයෙන් ඉවත් කර තිත් පමණක් තැබීම", "රළු අඟුරු කූරු රේඛා වීම", "රේඛා සියල්ල කෝදුවෙන් ඇඳීම", "රේඛාවේ සියුම් බව රැකගනිමින්ම මුහුණු හා ආභරණවල විස්තර වැඩි වී තිබීම පොළොන්නරු ලක්ෂණයකි."),
        q("තිවංක පිළිමගෙයි ඇති 'බෝධිසත්ව කුමාරවරුන් හා දෙවිවරුන්' ඇඳ ඇති ආකාරයේ කැපී පෙනෙන ආභරණ අංගය කුමක්ද?", "උස් මකුට ඔටුණු, උරමාලා හා මනරම් සළු පටි", "යුද හෙල්මට් සහ සපත්තු", "කිසිදු ආභරණයක් නොතිබීම", "නූතන අත් ඔරලෝසු", "ඉන්දීය චෝල හා පාල ආභාසය මුසු වූ උසස් රාජකීය ආභරණ මෝස්තර මෙහි දැකිය හැක."),
        q("තිවංක පිළිමගෙයි සිතුවම්වල ඇඳ ඇති 'සංකස්සපුර' දර්ශනයේ දෙව්ලොව සිට වැඩමවන බුදු රුවට සෙවණ දෙන චාමර හා ඡත්‍ර දරන්නේ කවුද?", "ශක්‍ර සහ මහා බ්‍රහ්මයා", "විජය සහ පඬුවස්දෙව්", "රාමා සහ ලක්ෂ්මණ", "මහසෙන් සහ කාශ්‍යප", "බෞද්ධ සම්ප්‍රදාය අනුව ශක්‍රයා සංඛය පිඹිමින්ද මහා බ්‍රහ්මයා සේසත් දරමින්ද වැඩම කළ බව දැක්වේ."),
        q("පොළොන්නරු යුගයේ චිත්‍ර කලාවේදී 'ත්‍රිමාණ බව' (Modeling) පෙන්වීම සඳහා තිවංක ශිල්පීන් කළේ කුමක්ද?", "දාර අඳුරු කර මැද ලා කිරීම", "තනි පැතලි වර්ණ පමණක් තැබීම", "බිත්තිය හාරා කැටයම් කිරීම", "රන් කඩදාසි ඇලවීම", "මහනුවර යුගයේ මෙන් පැතලි නොවී, වර්ණ සෙවණැලි මගින් පරිමාව දැක්වීම පොළොන්නරුවේද පැවතුණි."),
        q("තිවංක පිළිමගෙයි පිටත බිත්තිවල ඇති බදාම මූර්තිවලට අමතරව ඇතුළත සිතුවම් 'සංරක්ෂණය' කිරීමේදී පවතින ප්‍රධාන ගැටලුව කුමක්ද?", "පැරණි වහලය කඩා වැටීම නිසා සියවස් ගණනක් අව් වැසිවලට නිරාවරණය වීම", "සිතුවම් සියල්ල මුහුදු ජලයේ ගිලී තිබීම", "සිතුවම් පොළොව යට උමඟක පැවතීම", "වර්ණ තෙල් සායම් බවට පත්වීම", "තිවංක පිළිමගෙයි ගඩොල් වහලය බිඳී යාම නිසා බිතුසිතුවම් විශාල ප්‍රමාණයක් මැකී ගොස් ඇත."),
        q("පොළොන්නරු යුගයේ චිත්‍ර කලාවේ 'මහානාග හා තිවංක' සිතුවම්වල දක්නට ලැබෙන 'ගස්වැල් හා පරිසර නිරූපණය' කෙබඳුද?", "ශෛලිගත මල් හා පත්‍ර මෝස්තර", "නූතන ඡායාරූප වැනි භූ දර්ශන", "කිසිදු ගසක් හෝ මලක් නොඇඳීම", "වියුක්ත චතුරස්‍ර කොටු", "සුදුසු ස්ථානවල කුඩා මල්, ගස් හා සත්ව රූප ශෛලිගතව ඇඳ පරිසරය හඟවා ඇත."),
        q("පොළොන්නරුවේ 'සඳගිරි සෑය' හෝ 'රන්කොත් වෙහෙර' වැනි ස්ථානවල බාහිර බදාම කැටයම්වල පැවති විශේෂත්වය කුමක්ද?", "ගඩොල් මත හුණු බදාම විමාන රූප", "තනි කළුගල් වලින් කැපූ වහලය", "ලෝකඩ තහඩු ආවරණය", "දැව ලෑලි සැරසිලි", "බදාම මූර්ති කලාව (Stucco) පොළොන්නරු යුගයේ ගඩොල් දේවාල හා පිළිමගෙවල්වල බහුලව භාවිත විය."),
        q("තිවංක පිළිමගෙයි බිත්ති මත පිටතින් ඇති බදාම රූප (Stucco reliefs) වලින් නිරූපණය කර ඇත්තේ කවුරුන්ද?", "විමාන තුළ සිටින දෙවිවරුන්, නළඟනන් සහ ගණ රූප", "පෘතුගීසි වෙළඳුන්", "බ්‍රිතාන්‍ය සොල්දාදුවන්", "සිංහල රජවරුන්ගේ නම්", "තිවංක පිළිමගෙයි පිටත බිත්ති පවා අලංකාර බදාම දේව රූප හා වාමන රූපවලින් සරසා තිබේ."),
        q("පොළොන්නරුවේ 'ලංකාතිලක' විහාරයේ ඇතුළත හා පිටත බදාම නිර්මාණවල කැපී පෙනෙන ලක්ෂණය කුමක්ද?", "දැවැන්ත ගඩොල් බිත්ති මත විශිෂ්ට බදාම ප්‍රතිමා හා මකර තොරණ්", "කුඩා අඟල් දෙකේ ලෝකඩ රූප පමණක් වීම", "කළුගලින් පමණක් වහලය තැනීම", "තෙල් සායමින් පිටත පින්තාරු කිරීම", "මහා පරාක්‍රමබාහු යුගයේ ලංකාතිලක පිළිමගෙයි දැවැන්ත ගඩොල්-බදාම මූර්ති විශිෂ්ටය."),
        q("තිවංක පිළිමගෙයි ඇතුළත සිතුවම්වල 'ශුද්ධ වූ වෘත්ත හෙවත් ප්‍රභා මණ්ඩල' ඇඳ ඇත්තේ කුමන චරිත සඳහාද?", "බුදුන් වහන්සේ, බෝධිසත්වයන් හා ප්‍රධාන දෙවිවරුන් සඳහා", "දුෂ්ට චරිත හා යක්ෂයන් සඳහා", "සියලුම වන සතුන් සඳහා", "ගොඩනැගිලි හා ගස්වැල් සඳහා", "හිස වටා ඇති ප්‍රභා මණ්ඩල මගින් දිව්‍යමය හා උත්තරීතර ආධ්‍යාත්මික තත්ත්වය දැක්වේ."),
        q("පොළොන්නරු යුගයේ 'වෙස්සන්තර ජාතකය' තිවංක බිතුසිතුවම්වල ඇඳ ඇති ආකාරය පසුකාලීන මහනුවර යුගයේ සිතුවම්වලින් වෙනස් වන්නේ කෙසේද?", "පොළොන්නරුවේ ස්වභාවික රූප පරිමාව වැඩි අතර මහනුවර පැතලි රේඛා බහුල වීම", "පොළොන්නරුවේ වෙස්සන්තර කතාව නැති අතර මහනුවර ඇත", "මහනුවර සිතුවම් කළුගලින් කොටා ඇත", "පොළොන්නරුවේ සිතුවම් රෙදිවල ඇඳ ඇත", "සම්භාව්‍ය පරිමාවෙන් හෙබි පොළොන්නරු ආඛ්‍යානය මහනුවරදී සරල පැතලි ජන රීතියට මාරු විය."),
        q("තිවංක පිළිමගෙයි 'බිතුසිතුවම් බදාමයේ' විශේෂත්වයක් වන්නේ කුමන ස්තර ක්‍රමයද?", "රළු මැටි හා හුණු ස්තරය මත සියුම් හුණු පිරියම යෙදීම", "සිමෙන්ති මත වීදුරු කුඩු ඇතිරීම", "ලී ලෑලි මත තීන්ත ගෑම", "ප්ලාස්ටික් පුවරු ඇලවීම", "ගඩොල් බිත්තියට තදින් බැඳෙන හුණු, වැලි හා මැටි ස්තර පොළොන්නරු බිතුසිතුවම්වල භාවිත විය."),
        q("පොළොන්නරු යුගයේ 'විද්‍යාධර ගුහාවේ' බිතුසිතුවම් සහිත ලෙන අයත් වන්නේ කුමන ප්‍රකට ප්‍රතිමා සංකීර්ණයටද?", "උත්තරාරාමය හෙවත් ගල් විහාරයට", "නිශ්ශංකලතා මණ්ඩපයට", "හැටදාගෙයට", "තූපාරාමයට", "ගල් විහාරයේ හිටි පිළිමයට හා සැතපෙන පිළිමයට අතරමැද විජ්ජාධර ගුහාව පිහිටා ඇත."),
        q("තිවංක පිළිමගෙයි සිතුවම් මුලින්ම විධිමත්ව පිටපත් කර වාර්තා කිරීමට දායක වූ විද්වතුන් අතරට අයත් වන්නේ කවුද?", "එච්. සී. පී. බෙල් සහ ආනන්ද කුමාරස්වාමි", "ලියොනාඩෝ සහ රෆායල්", "පිකාසෝ සහ මැටිස්", "ඇලෙක්සැන්ඩර් සහ නැපෝලියන්", "1909 පමණ සිට බෙල් මහතා හා පසුකාලීන පුරාවිද්‍යාඥයන් තිවංක සිතුවම් පිටපත් කළහ."),
        q("පොළොන්නරුවේ බිතුසිතුවම්වල 'රූපවල ඇඳුම් පැළඳුම්' දෙස බලන විට එම යුගයේ පැවති කුමන සංස්කෘතික බලපෑමක් පෙනේද?", "දකුණු ඉන්දීය චෝල ආභාසය", "යුරෝපීය වික්ටෝරියානු බලපෑම", "ජපන් සමුරායි බලපෑම", "මිසර පාරාවෝ බලපෑම", "දකුණු ඉන්දීය ආභාසය ලත් ඔටුණු, සළු හා නර්තන ඉරියව් පොළොන්නරු සිතුවම්වල දිස්වේ."),
        q("තිවංක පිළිමගෙයි 'බුදුන් වහන්සේ වැඩ සිටින පසුබිමේ' දැකිය හැකි අලංකරණ අංගය කුමක්ද?", "සිංහාසනය, ප්‍රභා මණ්ඩලය හා කිඳුරු-මකර සැරසිලි", "නූතන වීදුරු ජනෙල්", "කර්මාන්තශාලා යන්ත්‍ර", "මුහුදු නැව් හා බෝට්ටු", "රාජකීය පූජනීය බව පෙන්වන අලංකාර ආසන හා තොරණ් බුදු රුව වටා සිතුවම් කර ඇත."),
        q("පොළොන්නරු යුගයේ චිත්‍ර කලාවේදී 'නිල් වර්ණය' අඩුවෙන් හෝ විරලව දක්නට ලැබුණද එය කුමන ඛනිජයෙන් හෝ ශාකයෙන් ලබා ගත්තේද?", "නිල් අවරිය (Indigo) හෝ ලැපිස් ලාසුලි ඛනිජයෙන්", "ගුරුගල් පිළිස්සීමෙන්", "කහ හුණු මිශ්‍ර කිරීමෙන්", "අඟුරු දිය කිරීමෙන්", "පොළොන්නරුවේ ඇතැම් ධාතු ගර්භ හා බිතුසිතුවම්වල ශාකමය නිල් අවරිය භාවිත කළ බවට සාධක ඇත."),
        q("තිවංක පිළිමගෙයි බිත්තිවල ඇඳ ඇති 'නැටුම් හා සංගීත' දර්ශනවලින් ප්‍රකට වන්නේ කුමක්ද?", "පූජා සඳහා නැටුම් හා වාදනය යෙදීම", "විහාරය තුළ නාට්‍ය ශාලාවක් පැවති බව", "සටන් කලා පුහුණු කළ බව", "සර්කස් කණ්ඩායමක් සිටි බව", "දේව පූජා හා මංගල අවස්ථාවලදී බෙර හා වීණා වයන දිව්‍ය රූප එහි ඇඳ තිබේ."),
        q("පොළොන්නරුවේ පිහිටි 'දිඹුලාගල මාරවීදිය' සිතුවම්වල ප්‍රධාන ලක්ෂණයක් වූයේ කුමක්ද?", "සියුම් වර්ණ සෙවණැලි සහිතව පූජනීය බෞද්ධ දර්ශන ඇඳ තිබීම", "ප්‍රාග් ඓතිහාසික කෙටුම් පමණක් තිබීම", "තෙල් සායමින් කැන්වස්වල ඇඳ තිබීම", "සතුන්ගේ ඇටසැකිලි ඇඳ තිබීම", "වර්ණවත් හුණු බදාම මත අනුරාධපුර-පොළොන්නරු සංක්‍රාන්ති ශෛලියෙන් බෞද්ධ සිතුවම් ඇඳ තිබුණි."),
        q("තිවංක පිළිමගෙයි ඇති 'බිතුසිතුවම්' ශ්‍රී ලංකාවේ චිත්‍ර කලා පරිණාමයේ කුමන පාලමක් ලෙස ක්‍රියා කරයිද?", "අනුරාධපුර සම්භාව්‍ය කලාව හා මහනුවර ජාතක කතා සිතුවම් කලාව අතර පාලමක් ලෙස", "ප්‍රාග් ඓතිහාසික හා යුරෝපීය නූතන කලාව අතර පාලමක් ලෙස", "චීන හා මිසර කලාව අතර පාලමක් ලෙස", "ග්‍රීක හා රෝම කලාව අතර පාලමක් ලෙස", "සීගිරි ත්‍රිමාණ බවත් මහනුවර ජාතක කතා ආඛ්‍යාන පිළිවෙතත් තිවංකයේදී එකට හමු වේ."),
        q("පොළොන්නරු යුගයේ 'කැටයම් හා සිතුවම්' දෙකෙහිම නිතර දක්නට ලැබෙන මුහුණු ස්වරූපය කෙබඳුද?", "රවුම් වූ මුහුණු හා සියුම් ඇස්-බැම", "සම්පූර්ණ ත්‍රිකෝණාකාර මුහුණු", "රළු හා කෝපාවිෂ්ට මුහුණු", "මුහුණු නොමැති හිස් සිරුරු", "පොළොන්නරු යුගයේ චරිතවල මුහුණු හැඩය වඩාත් පිරිපුන් හා විස්තරාත්මක බවක් පෙන්වයි."),
        q("තිවංක පිළිමගෙයි 'බිත්තිවල ඇති මකර හා ලියවැල්' බෝඩර් තීරුවල කාර්යය කුමක්ද?", "සිතුවම් පුවරු රාමු හා කොටස් කිරීම", "බිත්ති කඩා වැටීම වැළැක්වීම", "අකුරු ලියා තැබීම", "ජලය බැස යාමට කාණු සැදීම", "සංකීර්ණ ජාතක කතා පුවරු නරඹන්නාට පහසුවෙන් වෙන් කර හඳුනා ගැනීමට රාමු යොදා ඇත."),
        q("පොළොන්නරුවේ 'රන්කොත් වෙහෙර' හා 'කිරි වෙහෙර' හි පේසා වළලු හා වාහල්කඩ ආශ්‍රිතව භාවිත කළ කලා මාධ්‍යය කුමක්ද?", "හුණු බදාම මූර්ති හා වර්ණ පිරියම්", "කළුගල් වාත්තු කලාව", "වීදුරු මොසැයික්", "දැව කැටයම් පමණක්", "කිරි වෙහෙරේ හා ලංකාතිලකයේ සියුම් බදාම මූර්ති අලංකරණ අදටත් දක්නට ඇත."),
        q("පොළොන්නරු යුගයේ බිතුසිතුවම්වල 'සමූහගත රූප' ඇඳීමේදී චරිත එකිනෙකා කෙරෙහි දක්වන සම්බන්ධය පෙන්වන්නේ කෙසේද?", "දෑත් අභිනය, බැල්ම සහ හිස් ඇල කිරීම මගින් සජීවී සංවාදයක් මවා පෑමෙන්", "සියල්ලන් එකම පැත්ත බලාගෙන සිටීමෙන්", "රූප අතර කළු බිත්ති බැඳීමෙන්", "චරිතවල නම් ලියා ඊතල ඇඳීමෙන්", "නළඟනන් හා දෙවිවරුන් එකිනෙකා දෙස බලමින් අත්ලෙන් ඉඟි කරන අයුරු තිවංකයේ දිස්වේ."),
        q("පොළොන්නරුවේ 'වැලිපිටිය' හෝ 'තිවංක' සිතුවම්වල දැකිය හැකි 'නෙළුම් මල් පොකුරු' මගින් සිදු වන්නේ කුමක්ද?", "හිස් ඉඩ පිරවීම හා පූජනීය බව", "වෙළඳපොළක් නිරූපණය කිරීම", "වර්ණ පරීක්ෂා කිරීම", "වන සතුන් සැඟවීම", "ආකාශයේ වැටෙන මල් හා නෙළුම් පොකුරු ආගමික සිතුවමට සුන්දර පූජනීය බවක් එක් කරයි."),
        q("පොළොන්නරු යුගයේ බිතුසිතුවම් අධ්‍යයනය කිරීමේදී 'මහාචාර්ය චාල්ස් ගොඩකුඹුර' හා 'සෙනරත් පරණවිතාන' වැන්නන් කළ සේවය කුමක්ද?", "සිතුවම් කතා පුවත් නිවැරදිව හඳුනාගෙන ලේඛනගත කිරීම හා සංරක්ෂණය", "සිතුවම් මත නව කවි ලිවීම", "සිතුවම් කෞතුකාගාරවලින් ඉවත් කිරීම", "බිත්ති සුදු හුණු ගා වැසීම", "තිවංක පිළිමගෙයි ජාතක කතා හා දේවාවරෝහණය වැනි දර්ශන නිවැරදිව අර්ථකථනය කළේ ඔවුන්ය."),
        q("තිවංක පිළිමගෙයි ඇති 'බුදු රුවේ චීවරය' ඇඳ ඇති වර්ණය සහ රැලි ස්වභාවය කුමක්ද?", "රතු හෝ කහ පැහැති සිවුරේ මෘදු රැලි හා සෙවණැලි දැක්වීම", "නිල් පැහැති කොටු රෙද්දක් ලෙස", "කළු පැහැති ඝන කබායක් ලෙස", "සුදු පැහැති රැලි රහිත තීරුවක් ලෙස", "ගෞරවනීය රක්ත-කහ පැහැති චීවරය රිද්මයානුකූල රැලි සහිතව ඇඳ ඇත."),
        q("පොළොන්නරු යුගයේ චිත්‍ර කලාව හදිසියේම පරිහානියට පත් වී අවසන් වීමට හේතු වූ ප්‍රධාන සිදුවීම කුමක්ද?", "කාලිංග මාඝ ආක්‍රමණය හා මාරුවීම", "කාශ්‍යප රජු සීගිරියට යාම", "ලන්දේසි ආක්‍රමණය", "ගංවතුරකින් මුළු රට යටවීම", "මාඝගේ ආක්‍රමණයත් සමඟ රජරට කලා කේන්ද්‍ර විනාශ වී රාජධානි දඹදෙණිය දෙසට සංක්‍රමණය විය."),
        q("පොළොන්නරුවේ 'තිවංක පිළිමගෙයි' පිවිසුමෙහි පිටත බිත්තිවල ඇඳ තිබූ සිතුවම් ශේෂ හා ඇතුළත සිතුවම් අතර ඇති සම්බන්ධය කුමක්ද?", "ඇතුළත හා පිටත බෞද්ධ කතා හා දේව රූප", "පිටත කිසිදු සැරසිල්ලක් නොතිබීම", "පිටත තෙල් සායමින් ඇඳීම", "ඇතුළත සතුන් පමණක් තිබීම", "පිටත බදාම දේව රූපද ඇතුළත බිතුසිතුවම්ද එකම ආගමික සංකල්පයක් ඉදිරිපත් කරයි."),
        q("පොළොන්නරු යුගයේ චිත්‍ර කලාව අධ්‍යයනය කරන O/L සිසුවෙකුට තිවංක පිළිමගෙයින් උගත හැකි ප්‍රධාන චිත්‍ර කලා පාඩම කුමක්ද?", "සංකීර්ණ සමූහ රූප සංයුතිය හා ආගමික කතා ආඛ්‍යාන කලාව", "වියුක්ත කම්බි මූර්ති සෑදීම", "නූතන ග්‍රැෆික් පරිගණක මෘදුකාංග", "ජපන් ඔරිගාමි කඩදාසි නැමීම", "බොහෝ චරිත එක් තලයක ක්‍රමානුකූලව සංයෝජනය කරන ආකාරය තිවංකයෙන් උගත හැක."),
        q("තිවංක පිළිමගෙයි ඇති 'බුදුන් වහන්සේට බ්‍රහ්ම හා ශක්‍ර පවන් සලන හා මල් පූජා කරන' දර්ශනයේ පවතින භාවය කුමක්ද?", "ශාන්ත භක්තිය හා දිව්‍යමය ගෞරවය", "යුදමය කෝපය හා බිය", "විනෝදජනක හාස්‍ය රසය", "වෙහෙසකර ශෝකී බව", "සමස්ත සංයුතියම බුදුන් වහන්සේ වෙත යොමු වූ උත්තරීතර භක්ති රසය පළ කරයි."),
        q("පොළොන්නරු යුගයේ 'මූර්ති හා බිතුසිතුවම්' යන දෙඅංශයේම දක්නට ලැබෙන ප්‍රධාන පරිවර්තනය කුමක්ද?", "දේශීය සම්ප්‍රදාය තුළට දකුණු ඉන්දීය ආභාසය අවශෝෂණය කර ගැනීම", "සම්පූර්ණයෙන්ම යුරෝපීය ශෛලිය වැළඳ ගැනීම", "ප්‍රාග් ඓතිහාසික ගල් ආයුධ යුගයට යාම", "මැටි පමණක් භාවිත කර කළුගල් අත්හැරීම", "චෝල පාලන සමයෙන් පසු විජයබාහු හා පරාක්‍රමබාහු යුගවල දකුණු ඉන්දීය හා හෙළ කලා සම්මිශ්‍රණයක් බිහිවිය."),
        q("පොළොන්නරුවේ 'තිවංක' පිළිමගෙයි 'බිත්ති මතුපිට තෙතමනය හා පුස්' ඇතිවීමෙන් සිතුවම් විනාශ වීම වැළැක්වීමට ගත් පියවර කුමක්ද?", "ආරක්ෂිත පියස්සක් ඉදිකිරීම හා රසායනික පුරාවිද්‍යා සංරක්ෂණය", "සිතුවම් සබන් දමා සේදීම", "සිතුවම් උඩින් නව සිමෙන්ති ගෑම", "බිත්ති කඩා කෞතුකාගාරයට ගෙන යාම", "ආරක්ෂිත වහලයක් යොදා වාතාශ්‍රය හා තෙතමනය පාලනය කිරීමෙන් ඉතිරි සිතුවම් රැක ගැනේ."),
        q("තිවංක පිළිමගෙයි සිතුවම්වල 'සමහර සතුන්ගේ (හාවා, කැස්බෑවා, වඳුරා) රූප' ජාතක කතා තුළ ඇඳ ඇති ආකාරය කෙබඳුද?", "සත්වයාගේ ස්වාභාවික චලන හා හැඩය සජීවී ලෙස මානුෂීය හැඟීමෙන් දැක්වීම", "ජ්‍යාමිතික චතුරස්‍ර කොටු ලෙස ඇඳීම", "කිසිදු සතෙකු නොඇඳ නම් පමණක් ලිවීම", "සතුන් රෞද්‍ර රාක්ෂයන් ලෙස ඇඳීම", "සස ජාතකයේ හාවා හා අනෙකුත් සතුන් ඉතා සංවේදී හා ස්වභාවික ලෙස නිරූපණය කර ඇත."),
        q("පොළොන්නරුවේ 'නිශ්ශංකමල්ල රජුගේ රාජ සභාව' හා ඒ අවට ගොඩනැගිලිවල තිබූ බිතුසිතුවම් ශේෂවලින් පෙනෙන්නේ කුමක්ද?", "ආගමික ස්ථාන මෙන්ම රාජකීය ගොඩනැගිලිද සිතුවමින් සරසා තිබූ බව", "රාජ සභාවේ කිසිදු කලාවක් නොතිබූ බව", "සියල්ල කළු පැහැයෙන් පමණක් ගා තිබූ බව", "වීදුරු කැබලි පමණක් තිබූ බව", "පොළොන්නරු යුගයේ රාජකීය හා ආගමික ගෘහ නිර්මාණකරණයේදී බිතුසිතුවම් හා බදාම මූර්ති නිතර යෙදිණි."),
        q("තිවංක පිළිමගෙයි ඇති 'අසංඛවතී' හා 'මෛත්‍රීබල' ජාතක සිතුවම්වල කැපී පෙනෙන 'නාට්‍යමය බව' මතු කර ඇත්තේ කුමකින්ද?", "චරිතවල අංග චලනය, මුහුණු ඉරියව් සහ ශරීර හැරවීම්වලින්", "රූප මත වචන ලියා තැබීමෙන්", "සියලු චරිත නිශ්චලව හිටුවා තැබීමෙන්", "පසුබිම සම්පූර්ණයෙන් කළු කිරීමෙන්", "කතා පුවතේ සිදුවීම් පේළිය චරිතවල ක්‍රියාශීලී ඉරියව් මගින් රඟදක්වන සේ ඇඳ ඇත."),
        q("පොළොන්නරු යුගයේ චිත්‍ර කලාවේදී 'මුහුණේ දෑස් ඇඳීමේ' සියුම් වෙනසක් ලෙස දක්නට ලැබෙන්නේ කුමක්ද?", "නෙළුම් පෙති ඇස් හා උස් ඇහිබැම", "ඇස් සම්පූර්ණ හිස් රවුම් වීම", "ඇස් එකක් පමණක් ඇඳීම", "ඇස්වලට අව් කණ්ණාඩි ඇඳීම", "සම්භාව්‍ය ඇස් ඇඳීමේ ක්‍රමය දිගටම පවත්වා ගනිමින් වඩා තීව්‍ර රේඛාවක් භාවිත කර ඇත."),
        q("පොළොන්නරුවේ 'ගල් විහාර විජ්ජාධර ගුහාවේ' බිතුසිතුවම් සැලකෙන්නේ කුමන ප්‍රතිමා අසල ඇති කලා කෘති ලෙසද?", "ගල් විහාරයේ හිඳි හා හිටි පිළිම අතර පිහිටි ලෙන් පිළිමය දෙපස බිත්තිවල", "පරාක්‍රමබාහු රජ පිළිමය පිටුපස", "සත්මහල් ප්‍රාසාදයේ මුදුනේ", "වැව් බැම්මේ සොරොව්ව ඇතුළත", "විජ්ජාධර ගුහාවේ හිඳි බුදු පිළිමය වන්දනා කරන දේව රූප එහි ඇතුළු බිත්තිවල ඇඳ තිබේ."),
        q("තිවංක පිළිමගෙයට 'තිවංක' යන නම ලැබී ඇත්තේ කුමන කලාත්මක හේතුවක් නිසාද?", "ඇතුළත බුදු පිළිමය ත්‍රිභංග නිසා", "බිත්ති තුනක් පමණක් ඇති නිසා", "පිළිම තුනක් තැබූ නිසා", "දොරවල් තුනක් ඇති නිසා", "හිස, කඳ සහ උකුළ යන තුන් පොළකින් නැමුණු ත්‍රිභංග හිටි බුදු පිළිමය නිසා මෙය තිවංක පිළිමගෙය විය."),
        q("තිවංක පිළිමගෙයි ඇති දැවැන්ත ත්‍රිභංග බුදු පිළිමය නිර්මාණය කර ඇත්තේ කුමන ද්‍රව්‍යයකින්ද?", "ගඩොල් සහ සවිමත් හුණු බදාමයෙන්", "තනි කළුගල් පර්වතයකින්", "ඝන ලෝකඩ වාත්තුවකින්", "කොස් ලී කඳන්වලින්", "මීටර් 8කට වඩා උස තිවංක හිටි පිළිමය ගඩොලින් බැඳ හුණු බදාමයෙන් නිමවා තිබුණි."),
        q("තිවංක පිළිමගෙයි ඇතුළත සිතුවම් 'නරඹන්නාට කියවීමට' සකස් කර ඇති ආකාරය කෙබඳුද?", "ප්‍රදක්ෂිණා මාර්ගය අනුව ගමන් කරන විට ජාතක කතා පෙළට පෙනෙන සේ", "වහලය මුදුනේ පමණක් කුඩාවට ඇඳීමෙන්", "පොළොව යට ඇඳ තිබීමෙන්", "ඉහළ සිට පහළට ආපසු හැරවීමෙන්", "විහාරයට ඇතුළු වී පිළිමය වටා ගමන් කරන බැතිමතාට කතා පෙළ ක්‍රමයෙන් දැකගත හැකි විය."),
        q("පොළොන්නරු යුගයේ චිත්‍ර කලාවේදී 'ගෘහ නිර්මාණ හා මූර්ති' සමඟ බිතුසිතුවම්වල පවතින එකමුතුකම කුමක්ද?", "වාස්තු විද්‍යාව, බදාම මූර්ති හා සිතුවම් එකම ආධ්‍යාත්මික අරමුණකට එක්වීම", "එකිනෙකට සම්පූර්ණයෙන් විරුද්ධ වීම", "සිතුවම් කිසිදා ගොඩනැගිලි තුළ නොතිබීම", "ගොඩනැගිලි සියල්ල ලීයෙන් පමණක් තැනීම", "තිවංකය හා ලංකාතිලකය යනු ගෘහ නිර්මාණ, මූර්ති හා සිතුවම් ත්‍රිත්වයේම සංකලනයකි."),
        q("තිවංක පිළිමගෙයි ඇඳ ඇති 'කාලගෝල කතාව' හෝ වෙනත් ජාතක කතාවල සාමාන්‍ය ජන චරිත දැක්වෙන්නේ කෙසේද?", "විවිධ ශරීර හැඩතල, ඉරියව් සහ ජන ජීවිත ලක්ෂණ සහිතව", "සියලු දෙනාම රජවරුන් මෙන් ඔටුණු පළඳවා", "කිසිදු මුහුණක් නොපෙනෙන සේ", "රොබෝවරුන් මෙන් එකම ඉරියව්වෙන්", "සමාජයේ විවිධ තරාතිරම්වල මිනිසුන්ගේ චරිත ලක්ෂණ කලාකරුවා දක්ෂ ලෙස දක්වා ඇත."),
        q("පොළොන්නරු යුගයේ 'විජ්ජාධර ගුහාවේ' සිතුවම් සහ 'තිවංක පිළිමගෙයි' සිතුවම් යන දෙකෙහිම කාල නිර්ණය කුමක්ද?", "ක්‍රි.ව. 12 වන සියවසේ මහා පරාක්‍රමබාහු යුගය", "ක්‍රි.ව. 5 වන සියවසේ කාශ්‍යප යුගය", "ක්‍රි.ව. 18 වන සියවසේ කීර්ති ශ්‍රී යුගය", "ක්‍රි.ව. 20 වන සියවසේ නූතන යුගය", "මහා පරාක්‍රමබාහු රජුගේ කලා පුනරුදය යටතේ මෙම විශිෂ්ට සිතුවම් බිහිවිය."),
        q("පොළොන්නරුවේ 'තිවංක පිළිමගෙයි' බදාම තට්ටු මත ඇඳ ඇති සිතුවම්වල 'වර්ණ ශ්‍රේණිගත කිරීම' (Gradation) හඳුනාගත හැකි තැනක් කුමක්ද?", "දෙවිවරුන්ගේ හා බුදුන් වහන්සේගේ මුහුණු හා බාහු වටකුරු බව දැක්වීමේදී", "බිත්ති බෝඩර්වල තනි රතු තීරුවේදී", "කිසිදු වර්ණ මිශ්‍රණයක් නොමැති වීම", "සියලු තැන් කළු අඟුරෙන් පිරවීමේදී", "සිරුරේ මාංශ පේශි හා වටකුරු බව පෙන්වීමට සෙවණැලි තාක්ෂණය යොදාගෙන ඇත."),
        q("පොළොන්නරු යුගයේ බිතුසිතුවම්වල දැකිය හැකි 'විශේෂිත ගස් හා පුෂ්ප' අතර ප්‍රමුඛ වන්නේ මොනවාද?", "නා, සපු, නෙළුම් සහ කෙසෙල් වැනි දේශීය ශාක", "පයින් හා මේපල් ගස්", "කාන්තාර පතොක් ගස්", "ටියුලිප් සහ ලැවෙන්ඩර් මල්", "දේශීය ශාක පද්ධතිය කලාකරුවාගේ පරිසර නිරීක්ෂණයට හසු වී සිතුවම්වලට එක්ව ඇත."),
        q("තිවංක පිළිමගෙයි 'බුදු සිරිතේ සිදුවීම්' ඇඳ ඇති ගර්භගෘහ බිත්තිවල ඇති වර්ණවත් භාවය හා රේඛා සංයමය ගැන පවසන්නේ කුමක්ද?", "ලංකාවේ බෞද්ධ ආඛ්‍යාන චිත්‍ර කලාවේ ඉහළම තාක්ෂණික මට්ටමක් එහි පවතින බව", "එය ළමුන් විසින් ඇඳි රළු කුරුටු සටහන් බව", "කිසිදු අධ්‍යාත්මික අගයක් නොමැති බව", "සම්පූර්ණයෙන්ම විදේශීය චිත්‍ර පිටපත් කිරීමක් බව", "මහා පරාක්‍රමබාහු යුගයේ චිත්‍ර කලා සංවර්ධනය තිවංක සිතුවම් මගින් ලොවට විදහා දැක්වේ."),
        q("පොළොන්නරු යුගයේ චිත්‍ර කලාව පිළිබඳ හැදෑරීමේදී 'පුල්ලිගොඩ' සිතුවම් තුළ දක්නට ලැබෙන 'රැවුල් සහිත පුද්ගලයා' කවුරුන් ලෙස අනුමාන කෙරේද?", "බ්‍රහ්මයා හෝ සෘෂිවරයෙක් / දේව රුවක්", "පෘතුගීසි නාවිකයෙක්", "බ්‍රිතාන්‍ය ආණ්ඩුකාරවරයෙක්", "රෝම සෙනෙට් සභිකයෙක්", "සුදු රැවුල හා ජටාව සහිත රුව බ්‍රහ්ම දේව හෝ ශ්‍රාවක රුවක් ලෙස හඳුනා ගැනේ."),
        q("තිවංක පිළිමගෙයි සිතුවම්වල 'සතුට හා භක්තිය' ප්‍රකාශ කිරීමට යොදාගෙන ඇති ප්‍රධාන සංකේතාත්මක ක්‍රියා මොනවාද?", "දොහොත් මුදුන් දී වැඳීම, මල් ඉසීම හා නර්තන ඉරියව් පෑම", "අවි ආයුධ ඔසවා ගෙන සිටීම", "මුහුණු හරවා බිත්තිය දෙස බැලීම", "පසුබිමට ඉවතට දුව යාම", "සමූහ රූප සියල්ලේ අභිනය හා මුද්‍රා බුදුන් වහන්සේ කෙරෙහි ගෞරවය හඟවයි."),
        q("පොළොන්නරුවේ 'තිවංක පිළිමගෙය' බෞද්ධ සංස්කෘතික උරුමයක් ලෙස ලෝක උරුම නගරය තුළ අතිශය වැදගත් වන්නේ ඇයි?", "පොළොන්නරුවේ සම්පූර්ණ බිතුසිතුවම් සමූහය", "එහි විශාලතම දාගැබ පිහිටි බැවින්", "එය පැරණි වෙළඳ මධ්‍යස්ථානයක් වූ බැවින්", "එහි රජ මාලිගාව පිහිටි බැවින්", "පොළොන්නරුවේ බොහෝ විහාර බිතුසිතුවම් විනාශ වී ඇති නමුත් තිවංකයේ ශේෂ ඉතා වැදගත් සාක්ෂියකි."),
        q("තිවංක පිළිමගෙයි සිතුවම්වල 'වර්ණක පුවරුව' (Color Palette) සීගිරිය හා සසඳන විට ඇති වෙනසක් වන්නේ කුමක්ද?", "සීගිරියට වඩා තරමක් වැඩි උණුසුම් රතු-දුඹුරු ආධිපත්‍යයක් හා විවිධ වර්ණ සංකලන යෙදීම", "සීගිරියේ කිසිදු රතු පැහැයක් නොතිබීම", "තිවංකයේ සියලු සිතුවම් කළු-සුදු වීම", "තිවංකයේ කෘත්‍රිම ප්ලාස්ටික් ඩයි භාවිත කිරීම", "පොළොන්නරු සිතුවම්වල රතු, කහ සහ කොළ පැහැයන් ආඛ්‍යානමය ගැඹුර මතු කිරීමට මනාව යොදා ඇත."),
        q("පොළොන්නරු යුගයේ චිත්‍ර කලාව අධ්‍යයනයේදී 'ගල් විහාර විජ්ජාධර ගුහාවේ' සිතුවම්වල පවතින බුදුන් වහන්සේගේ හිස අසල සිටින දේව රුව කුමන ඉරියව්වකින් සිටීද?", "වඳිමින් හෝ චාමර සලමින් ගෞරව දක්වන ඉරියව්වෙන්", "සටන් කරන ඉරියව්වෙන්", "නිදා සිටින ඉරියව්වෙන්", "පිටුපස හැරී යන ඉරියව්වෙන්", "ගල් විහාර හිඳි බුදු පිළිමයට දෙපසින් ඇති බිත්තිවල දේව රූප නමස්කාර පූර්වකව ඇඳ තිබේ."),
        q("පොළොන්නරුවේ 'සඳකඩපහණ' හා 'බිතුසිතුවම්' අතර පොදු වන ආගමික හා කලාත්මක ලක්ෂණය කුමක්ද?", "සියුම් විස්තර අලංකරණය හා දකුණු ඉන්දීය සංස්කෘතික ආභාසය මුසු වූ බෞද්ධ සංකල්ප", "ප්‍රාග් ඓතිහාසික සරල කූරු රූප බව", "යුරෝපීය පුනරුද රේඛීය දෘෂ්ටිකෝණය", "කිසිදු සැරසිල්ලක් නැති රළු බව", "පොළොන්නරු යුගයේ සියලු කලාංගවල අලංකාර විස්තරාත්මක බව හා හෙළ-ඉන්දීය සම්මිශ්‍රණය පෙනේ."),
        q("තිවංක පිළිමගෙයි ඇඳ ඇති 'දිව්‍ය ලෝක දර්ශන' තුළින් චිත්‍ර ශිල්පියා පෙන්නුම් කර ඇති කුසලතාව කුමක්ද?", "සාමාන්‍ය මිනිස් ලෝකයේ රූප භාවිතයෙන් අදෘශ්‍යමාන දිව්‍යමය සුන්දරත්වය මවා පෑම", "අහසේ ගමන් කරන ගුවන් යානා ඇඳීම", "විද්‍යාත්මක තාරකා සිතියම් ඇඳීම", "වීදුරු මාලිගා සැලසුම් ඇඳීම", "වලාකුළු, මල්, ආභරණ හා ප්‍රභා මණ්ඩල මගින් දිව්‍ය ලෝකයේ සුන්දරත්වය ජීවමානව නිරූපණය කරයි."),
        q("පොළොන්නරු යුගයේ චිත්‍ර කලාව අවසන් වීමෙන් පසු ශ්‍රී ලංකාවේ බිතුසිතුවම් කලාව යළිත් ප්‍රබල ලෙස මතු වන්නේ කුමන යුගයේදීද?", "18 වන සියවසේ මහනුවර යුගයේදී", "ක්‍රි.පූ. 3 වන සියවසේදී", "සීගිරි කාශ්‍යප යුගයේදී", "21 වන සියවසේදී පමණක්", "දඹදෙණි-ගම්පොළ-කෝට්ටේ යුගවල පසුබෑමකින් පසු වැලිවිට සරණංකර හිමි හා කීර්ති ශ්‍රී රජු සමයේ මහනුවර යුගයේ නැගී ආවේය.")
    )
}
